import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    static int n, m;
    static long k;
    static long[] a;

    // Greedy slot filling from `start`: does the suffix fit in at most m slots?
    static boolean valid(int start) {
        long slots = 1, used = 0;
        for (int i = start; i < n; i++) {
            if (used + a[i] > k) {
                slots++;
                used = 0;
            }
            used += a[i];
            if (slots > m) return false;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        n = nextInt();
        m = nextInt();
        k = nextLong();
        a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Feasible starts form a suffix: binary search the earliest one.
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (valid(mid)) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(n - lo);
    }
}

